@import url('https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Xbox DNA — power green on carbon dark */
.theme-xbox-dna {
  --bg: oklch(0.164 0 0);
  --surface: oklch(0.200 0 0);
  --surface-2: oklch(0.239 0 0);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.686 0 0);
  --accent: oklch(0.627 0.170 149.2);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.622 0.168 143.2);
  --line: oklch(1 0 0 / 14%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.788 0.151 74.9);
  --danger: oklch(0.615 0.190 27.8);
  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Manrope", sans-serif;
  --font-body: "Manrope", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: none;
  --label-tracking: 0.04em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-xbox-dna h1,
.theme-xbox-dna h2,
.theme-xbox-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-xbox-dna { --font-ui: var(--font-display); background-image: radial-gradient(circle at 50% -20%, oklch(0.4 0.12 145 / 30%), transparent 50%); }
.theme-xbox-dna h1 { font-weight: 800; }
.theme-xbox-dna button:hover { box-shadow: 0 0 20px color-mix(in oklab, var(--accent) 55%, transparent); }
.theme-xbox-dna h2 { color: var(--accent); }

/* depth */
.theme-xbox-dna { background-image: repeating-linear-gradient(45deg, oklch(1 0 0 / 2%) 0 1px, transparent 1px 6px), radial-gradient(circle at 50% -20%, oklch(0.4 0.12 145 / 30%), transparent 50%); }
.theme-xbox-dna thead th { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.12em; color: var(--accent); border-bottom: 1px solid color-mix(in oklab, var(--accent) 45%, transparent); }
.theme-xbox-dna tbody td { border-bottom: 1px solid var(--line); }
.theme-xbox-dna tbody tr:hover td { background: color-mix(in oklab, var(--accent) 8%, transparent); }
.theme-xbox-dna a { color: oklch(0.780 0.150 148.0); text-underline-offset: 3px; }
.theme-xbox-dna a:hover { color: var(--accent-fg); text-decoration-color: var(--accent); }
.theme-xbox-dna ::selection { background: oklch(0.440 0.130 149.2); color: oklch(1 0 0); }
.theme-xbox-dna :is(button, a, input, select, textarea):focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; box-shadow: none; }
.theme-xbox-dna button:active { transform: translateY(1px); box-shadow: inset 0 2px 6px oklch(0 0 0 / 40%); }
.theme-xbox-dna kbd { font-family: var(--font-mono); font-size: 0.78em; padding: 0.12em 0.55em; border-radius: var(--radius-pill); background: var(--surface-2); border: 1px solid color-mix(in oklab, var(--accent) 40%, var(--line)); color: var(--accent); }
.theme-xbox-dna ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-xbox-dna ::-webkit-scrollbar-track { background: var(--bg); }
.theme-xbox-dna ::-webkit-scrollbar-thumb { background: color-mix(in oklab, var(--accent) 45%, var(--surface-2)); border-radius: 999px; border: 2px solid var(--bg); }
.theme-xbox-dna .label-caps { color: var(--accent); letter-spacing: 0.12em; }
.theme-xbox-dna .themed-border { border-color: color-mix(in oklab, var(--accent) 45%, var(--line)); }

/* alt mode: robot white — Series S shell, deep #107C10 green */
.theme-xbox-dna.alt-mode {
  --bg: oklch(0.98 0.000 0.0);
  --surface: oklch(0.955 0.000 0.0);
  --surface-2: oklch(0.92 0.000 0.0);
  --fg: oklch(0.17 0.005 270);
  --fg-muted: oklch(0.46 0.01 270);
  --accent: oklch(0.510 0.150 145.0);
  --accent-2: oklch(0.440 0.130 145.0);
  --line: oklch(0.87 0.005 270);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  background-image: none;
}
.theme-xbox-dna.alt-mode a { color: oklch(0.450 0.140 145.0); }
.theme-xbox-dna.alt-mode ::selection { background: oklch(0.510 0.150 145.0); color: oklch(1 0 0); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"], [class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
